(7493840, 1192980, 14476, '<td valign="top">Oh, nice one.  Y ou were out there in the rain and the patterns, shapes were perfect for this composition.</td>', 'Oh, nice one.  Y ou were out there in the rain and the patterns, shapes were perfect for this composition.', '2017-01-22 19:26:37.000000', NULL, 1),
