(7493956, 1193441, 81362, '<td valign="top">A glimpse into fairy worlds, natural elements combined with a delicate touch, a sideways glance that both enchants and warns, all done with careful choice of tones and textures. Beautifully done.</td>', 'A glimpse into fairy worlds, natural elements combined with a delicate touch, a sideways glance that both enchants and warns, all done with careful choice of tones and textures. Beautifully done.', '2017-01-23 09:11:43.000000', NULL, 1),
(7493957, 1193170, 81362, '<td valign="top">Abstract beauty, metal and rust making visual poetry together, existing  simply for what it is without demanding narrative, comfortable feeling despite the sharply defined edges in an undefined setting, and oddly familiar, like the strange corners of our lives.</td>', 'Abstract beauty, metal and rust making visual poetry together, existing  simply for what it is without demanding narrative, comfortable feeling despite the sharply defined edges in an undefined setting, and oddly familiar, like the strange corners of our lives.', '2017-01-23 09:16:42.000000', NULL, 1),
(7493962, 1193707, 96751, '<td valign="top">Warp drive. But are we racing towards a singular breach in the time space continuum, or away from it.</td>', 'Warp drive. But are we racing towards a singular breach in the time space continuum, or away from it.', '2017-01-23 09:48:02.000000', NULL, 1),
