INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7494255, 1193762, 12611, '<td valign="top">nice slice of life featuring the reality of an urban fruit vendor</td>', 'nice slice of life featuring the reality of an urban fruit vendor', '2017-01-24 08:23:52.000000', NULL, 1),
(7494256, 1193688, 12611, '<td valign="top">This has the feel of an album cover, with just enough unease and anticipation to cause a great deal of movement and emotion. Still ambivalent as to the crop /aspect ratio.</td>', 'This has the feel of an album cover, with just enough unease and anticipation to cause a great deal of movement and emotion. Still ambivalent as to the crop /aspect ratio.', '2017-01-24 08:25:32.000000', NULL, 1),
(7494257, 1193640, 12611, '<td valign="top">The feel of the grit of the sand, and the knowledge that we are all grains of sand on the universal beach...</td>', 'The feel of the grit of the sand, and the knowledge that we are all grains of sand on the universal beach...', '2017-01-24 08:26:35.000000', NULL, 1),
(7494258, 1193083, 12611, '<td valign="top">A top 3 shot for me. Bold and contrasty, malevolent trees threaten our protagonist on her quest- leaving blue skies and walking right into it...9</td>', 'A top 3 shot for me. Bold and contrasty, malevolent trees threaten our protagonist on her quest- leaving blue skies and walking right into it...9', '2017-01-24 08:30:24.000000', NULL, 1),
(7494259, 1193414, 12611, '<td valign="top">wonderfully put together.</td>', 'wonderfully put together.', '2017-01-24 08:30:41.000000', NULL, 1),
(7494260, 1193175, 12611, '<td valign="top">you have achieved a wonderful balance of color and lack there-of...</td>', 'you have achieved a wonderful balance of color and lack there-of...', '2017-01-24 08:32:11.000000', NULL, 1),
(7494261, 1193467, 12611, '<td valign="top">Nicely put together- there is a beauty in shapes that occur in nature and don''t, and in the real human nature of female form-and when put in a position and posture of pre-birth, one cannot help but look back towards the question "what is the soul"- or ahead to the realization that truth, beauty- represent soul.</td>', 'Nicely put together- there is a beauty in shapes that occur in nature and don''t, and in the real human nature of female form-and when put in a position and posture of pre-birth, one cannot help but look back towards the question "what is the soul"- or ahead to the realization that truth, beauty- represent soul.', '2017-01-24 08:36:39.000000', NULL, 1),
(7494262, 1193631, 12611, '<td valign="top">lovely darkness approaches...</td>', 'lovely darkness approaches...', '2017-01-24 08:36:57.000000', NULL, 1),
(7494265, 1193350, 39880, '<td valign="top">I like how you framed Longs in the middle with the forest in the foreground and clouds above.  The subdued colors are also nice.  My top pick in the challenge.</td>', 'I like how you framed Longs in the middle with the forest in the foreground and clouds above.  The subdued colors are also nice.  My top pick in the challenge.', '2017-01-24 09:26:14.000000', NULL, 1),
(7494266, 1193188, 39880, '<td valign="top">Nice and moody.  I like the dark.  I could picture this as a book cover.</td>', 'Nice and moody.  I like the dark.  I could picture this as a book cover.', '2017-01-24 09:26:55.000000', NULL, 1),
(7494267, 1193012, 39880, '<td valign="top">Nice abstract art.</td>', 'Nice abstract art.', '2017-01-24 09:27:17.000000', NULL, 1),
(7494269, 1193433, 39880, '<td valign="top">The blur gives it a nice abstract look.</td>', 'The blur gives it a nice abstract look.', '2017-01-24 09:32:09.000000', NULL, 1),
(7494271, 1193794, 39880, '<td valign="top">This is nice.  I like the silhouette and square crop.  I think if the vulture were dead center it would be even better.</td>', 'This is nice.  I like the silhouette and square crop.  I think if the vulture were dead center it would be even better.', '2017-01-24 09:35:22.000000', NULL, 1),
(7494272, 1193124, 39880, '<td valign="top">The B&amp;W with the grain gives this a surreal feel for me.  I like it.</td>', 'The B&W with the grain gives this a surreal feel for me.  I like it.', '2017-01-24 09:37:24.000000', NULL, 1),
(7494276, 1193393, 39880, '<td valign="top">I like the abstract look of this.  Might be a bit dark for my tastes.  Lighten it up some and I think it could be better.</td>', 'I like the abstract look of this.  Might be a bit dark for my tastes.  Lighten it up some and I think it could be better.', '2017-01-24 09:43:52.000000', NULL, 1),
(7494277, 1193320, 61234, '<td valign="top">Interesting. Held my attention for longer than most. A lot to see.</td>', 'Interesting. Held my attention for longer than most. A lot to see.', '2017-01-24 09:44:31.000000', NULL, 1),
(7494278, 1193314, 39880, '<td valign="top">The tree and background together make for an interesting look.  I like it.</td>', 'The tree and background together make for an interesting look.  I like it.', '2017-01-24 09:44:45.000000', NULL, 1),
(7494280, 1193170, 39880, '<td valign="top">The colors and patterns make for an interesting abstract.</td>', 'The colors and patterns make for an interesting abstract.', '2017-01-24 09:45:39.000000', NULL, 1),
(7494281, 1193787, 39880, '<td valign="top">A nice classic view of Venice.  I link a little sharpening would help.  And boost the colors just a little bit.</td>', 'A nice classic view of Venice.  I link a little sharpening would help.  And boost the colors just a little bit.', '2017-01-24 09:46:19.000000', NULL, 1),
